#define main oldmain
#include "verify28.cpp"
#undef main
#include <unordered_set>
using U=uint64_t;
struct Prom{int color,original,mask;};
struct Snap{array<int,64> board,ids;int ply;};
int maskbit(int t){return 1<<(t-2);}
bool geom(int t,int a,int z){int dx=abs(a%8-z%8),dy=abs(a/8-z/8);if(!dx&&!dy)return false;return t==2?dx*dy==2:t==3?dx==dy:t==4?(!dx||!dy):(!dx||!dy||dx==dy);}
bool hits(const Board& b,int t,int a,int z){if(!geom(t,a,z))return false;if(t==2)return true;int d=sign(z%8-a%8)+8*sign(z/8-a/8);for(int i=a+d;i!=z;i+=d)if(b[i])return false;return true;}
string signature(const Snap& s,const vector<Prom>& ps){array<int,2> fixed{};vector<int> masks[2];for(int a=0;a<64;a++){int p=s.board[a];if(!p||abs(p)==6)continue;int c=p>0?0:1;if(s.ids[a]>=0){int m=ps[s.ids[a]].mask;if(__builtin_popcount((unsigned)m)==1)fixed[c]+=1<<(4*(abs(p)-1));else masks[c].push_back(m);}else fixed[c]+=1<<(4*(abs(p)-1));}string sides[2];for(int c=0;c<2;c++){for(int i=0;i<5;i++)sides[c]+=char('a'+((fixed[c]>>(4*i))&15));sort(masks[c].begin(),masks[c].end());for(int m:masks[c])sides[c]+=char('A'+m);}if(sides[0]>sides[1])swap(sides[0],sides[1]);return sides[0]+":"+sides[1];}
bool symbolic(const string& l,vector<pair<string,int>>& fam){Board b{};int base[]={4,2,3,5,6,3,2,4};for(int i=0;i<8;i++){b[i]=base[i];b[i+8]=1;b[i+48]=-1;b[i+56]=-base[i];}array<int,64> ids;ids.fill(-1);vector<Prom> ps;vector<Snap> snaps;int c=1,ep=-1,quiet=0,n=32,ply=0;unordered_map<string,int> reps;istringstream f(l);string s;while(f>>s){if(s.size()!=4&&s.size()!=5)return false;for(int i:{0,2})if(s[i]<'a'||s[i]>'h'||s[i+1]<'1'||s[i+1]>'8')return false;string rep;for(int i=0;i<64;i++)rep+=char((abs(b[i])>=2&&abs(b[i])<=5?7*(b[i]>0?1:-1):b[i])+7);rep+=char(c+1);if(++reps[rep]>=5||quiet>=150)return false;int a=sq(s,0),z=sq(s,2),pr=s.size()==5?string("  nbrq").find(s[4]):0;int p=b[a],v=b[z],id=ids[a];bool cap=v||(abs(p)==1&&a%8!=z%8);if(pr<0||pr>5||!move(b,a,z,c,pr,ep))return false;if(id>=0){for(int t=2;t<=5;t++)if(!geom(t,a,z))ps[id].mask&=~maskbit(t);}if(cap&&!v)ids[z-8*c]=-1;ids[a]=-1;ids[z]=id;if(pr){ids[z]=ps.size();ps.push_back({c,pr,15});}int k=king(b,c);for(int i=0;i<64;i++)if(ids[i]>=0&&ps[ids[i]].color==-c){auto &q=ps[ids[i]];for(int t=2;t<=5;t++)if((q.mask&maskbit(t))&&hits(b,t,i,k))q.mask&=~maskbit(t);}if(cap)n--;quiet=(cap||abs(p)==1)?0:quiet+1;ep=abs(p)==1&&abs(a/8-z/8)==2?(a+z)/2:-1;c=-c;ply++;if(cap||pr)snaps.push_back({b,ids,ply});}if(!attack(b,king(b,c),-c))return false;for(int a=0;a<64;a++)if(b[a]*c>0)for(int z=0;z<64;z++){if(abs(b[a])==1&&(z/8==0||z/8==7)){for(int pr=2;pr<=5;pr++){Board t=b;if(move(t,a,z,c,pr,ep))return false;}}else{Board t=b;if(move(t,a,z,c,0,ep))return false;}}for(int i=0;i<64;i++)if(ids[i]>=0)ps[ids[i]].mask=maskbit(ps[ids[i]].original);for(auto q:ps)if(!(q.mask&maskbit(q.original)))return false;for(auto& s:snaps)fam.push_back({signature(s,ps),s.ply});return true;}
int main(int argc,char**argv){ifstream in(argv[1]);ofstream out(argv[2]);unordered_set<string> seen;string l;long good=0,bad=0,n=0;while(getline(in,l)){n++;vector<pair<string,int>> fam;if(symbolic(l,fam)){good++;for(auto& p:fam)if(seen.insert(p.first).second)out<<p.first<<' '<<n<<' '<<p.second<<'\n';}else bad++;if(n%10000==0)cerr<<n<<" valid "<<good<<" excluded "<<bad<<" families "<<seen.size()<<endl;}cerr<<"DONE "<<n<<" valid "<<good<<" excluded "<<bad<<" families "<<seen.size()<<endl;}
